using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using Microsoft.Win32;
public partial class TV {
 public class ApkInfo {public string File;public string Name;public string Package;public string Version;public string Error;}
 readonly List<string> importedApks=new List<string>();
 readonly Dictionary<string,ApkInfo> apkCache=new Dictionary<string,ApkInfo>();
 async Task<ApkInfo> InspectApk(string file){var f=new FileInfo(file);string cacheKey=f.FullName+"|"+f.Length+"|"+f.LastWriteTimeUtc.Ticks;ApkInfo info;if(apkCache.TryGetValue(cacheKey,out info))return info;info=new ApkInfo{File=f.FullName};try{string dump=await ProcessRun(Root+"tools/aapt.exe","dump badging "+Q(f.FullName),30000);var match=Regex.Match(dump,@"^package: name='([A-Za-z0-9_.]+)'",RegexOptions.Multiline);if(!match.Success)throw new Exception("无法读取有效的 APK 包信息");info.Package=match.Groups[1].Value;info.Version=Regex.Match(dump,@"^package:.*?versionName='([^']*)'",RegexOptions.Multiline).Groups[1].Value;info.Name=PreferredLabel(dump);if(string.IsNullOrWhiteSpace(info.Name))info.Name="未提供软件名称";}catch(Exception ex){info.Name="无法识别安装包";info.Error=ex.Message;}apkCache[cacheKey]=info;return info;}
 void ShowApkPage(){Heading("安装 APK","显示安装包中的软件名与完整包名，优先读取中文名称。可导入或拖入 APK，核对后安装。");var actions=new WrapPanel();body.Children.Add(actions);Add(actions,"导入 APK 文件",()=>ChooseApks());Add(actions,"全部安装",()=>Install(Directory.GetFiles(Root+"apps","*.apk").Concat(importedApks).Distinct(StringComparer.OrdinalIgnoreCase).ToArray()));Add(actions,"去安装桌面（向导第二步）",()=>Show("步骤2"));var list=new StackPanel{Margin=new Thickness(0,16,0,0)};body.Children.Add(list);PopulateApkCards(list);}
 async void PopulateApkCards(StackPanel list){var files=Directory.GetFiles(Root+"apps","*.apk").Concat(importedApks).Distinct(StringComparer.OrdinalIgnoreCase).ToList();foreach(string file in files){var title=Text("正在读取软件名…",18,"#202431");var package=Text("包名：读取中…",13);package.TextWrapping=TextWrapping.Wrap;package.IsEnabled=true;var detail=Text(System.IO.Path.GetFileName(file)+" · "+(new FileInfo(file).Length/1048576.0).ToString("F1")+" MB",12);var card=new StackPanel{Margin=new Thickness(18)};card.Children.Add(title);card.Children.Add(package);card.Children.Add(detail);var button=new Button{Content="安装",IsEnabled=false,Padding=new Thickness(20,9,20,9),Margin=new Thickness(0,10,0,0),HorizontalAlignment=HorizontalAlignment.Left,Background=Brushes.White,BorderBrush=Color("#DFE3EC")};string apk=file;button.Click+=(sender,args)=>{try{Install(new[]{apk});}catch(Exception ex){Report(ex.Message);}};card.Children.Add(button);list.Children.Add(new Border{Child=card,Background=Brushes.White,CornerRadius=new CornerRadius(14),BorderBrush=Color("#E2E6EF"),BorderThickness=new Thickness(1),Margin=new Thickness(4,0,4,10)});try{var info=await InspectApk(file);title.Text=info.Name;package.Text="包名："+(info.Package??"识别失败");package.ToolTip=info.Package;detail.Text=System.IO.Path.GetFileName(file)+" · "+(new FileInfo(file).Length/1048576.0).ToString("F1")+" MB"+(string.IsNullOrEmpty(info.Version)?"":" · 版本 "+info.Version);button.IsEnabled=info.Error==null;if(info.Error!=null){package.Text+=" · "+info.Error;package.Foreground=Color("#B04432");}}catch(Exception ex){title.Text="读取失败";package.Text=ex.Message;}}}
 void ImportApks(string[] files){if(busy){Report("当前任务执行中，请结束后导入 APK。");return;}if(files.Any(f=>!File.Exists(f)||!f.EndsWith(".apk",StringComparison.OrdinalIgnoreCase)))throw new Exception("只接受 APK 文件");foreach(string file in files)if(!importedApks.Contains(file,StringComparer.OrdinalIgnoreCase))importedApks.Add(file);Show("安装与桌面");}
}
